const TWO_PI = Math.PI * 2;
const SIN_N = 2048;
const SIN = new Float32Array(SIN_N + 2);
for (let i = 0; i <= SIN_N + 1; i++) SIN[i] = Math.sin((i / SIN_N) * TWO_PI);
function sinC(ph) { const f = ph * SIN_N; const i = f | 0; return SIN[i] + (SIN[i + 1] - SIN[i]) * (f - i); }
function hsin(x) { const f = x * SIN_N * 0.5; const i = f | 0; return SIN[i] + (SIN[i + 1] - SIN[i]) * (f - i); }

